try{
 if($_SERVER['REQUEST_METHOD']==='GET'){
  $st=$pdo->prepare("SELECT a.id,a.sede_id,a.nombre,a.whatsapp,a.correo,a.estado_administrativo,p.nombre plan_nombre,p.sesiones_semana,p.precio,h.hora_inicio,h.hora_fin,EXISTS(SELECT 1 FROM curso_intensivo_alumnos cia JOIN cursos_intensivos ci ON ci.id=cia.curso_intensivo_id WHERE cia.alumno_id=a.id AND ci.sede_id=a.sede_id AND ci.estado IN ('PROGRAMADO','EN_CURSO')) intensivo_activo FROM alumnos a LEFT JOIN planes p ON p.id=a.plan_actual_id AND p.sede_id=a.sede_id LEFT JOIN horarios h ON h.id=a.horario_preferido_id AND h.sede_id=a.sede_id WHERE a.id=:id LIMIT 1");$st->execute([':id'=>$aid]);$alumno=$st->fetch();if(!$alumno)out(['ok'=>false,'error'=>'Alumno no encontrado'],404);$sedeId=(string)$alumno['sede_id'];unset($alumno['sede_id']);
  $st=$pdo->prepare("SELECT folio,tipo,importe,metodo,fecha,estado,observacion FROM pagos WHERE alumno_id=:a ORDER BY fecha DESC,folio DESC LIMIT 24");$st->execute([':a'=>$aid]);$pagos=$st->fetchAll();
  $st=$pdo->prepare("SELECT id,fecha_desde,fecha_hasta,motivo,estado,created_at FROM avisos_ausencia WHERE alumno_id=:a ORDER BY fecha_desde DESC,created_at DESC LIMIT 24");$st->execute([':a'=>$aid]);$avisos=$st->fetchAll();
  $st=$pdo->prepare("SELECT rr.id,rr.estado,rr.created_at,rr.used_at,se.fecha fecha_ausencia FROM reposiciones_regulares rr JOIN asistencias aa ON aa.id=rr.ausencia_asistencia_id JOIN sesiones se ON se.id=aa.sesion_id JOIN horarios h ON h.id=se.horario_id WHERE rr.alumno_id=:a AND h.sede_id=:sede ORDER BY se.fecha DESC");$st->execute([':a'=>$aid,':sede'=>$sedeId]);$repos=$st->fetchAll();
  $st=$pdo->prepare("SELECT ci.id,ci.fecha_inicio,ci.fecha_fin,ci.estado,cia.reposiciones_justificadas,cia.reposiciones_cancelacion,h.hora_inicio,h.hora_fin FROM curso_intensivo_alumnos cia JOIN cursos_intensivos ci ON ci.id=cia.curso_intensivo_id LEFT JOIN horarios h ON h.id=cia.horario_id AND h.sede_id=ci.sede_id WHERE cia.alumno_id=:a AND ci.sede_id=:sede ORDER BY ci.fecha_inicio DESC LIMIT 6");$st->execute([':a'=>$aid,':sede'=>$sedeId]);$intensivos=$st->fetchAll();
  $st=$pdo->prepare("SELECT id,titulo,cuerpo,audiencia,vigencia_desde,vigencia_hasta,created_at FROM mensajes WHERE sede_id=:sede AND activo=1 AND (vigencia_desde IS NULL OR vigencia_desde<=CURDATE()) AND (vigencia_hasta IS NULL OR vigencia_hasta>=CURDATE()) AND (audiencia='TODOS' OR (audiencia='ALUMNO' AND alumno_id=:a) OR (audiencia='REGULARES' AND :i1=0) OR (audiencia='INTENSIVOS' AND :i2=1)) ORDER BY created_at DESC LIMIT 20");$st->execute([':sede'=>$sedeId,':a'=>$aid,':i1'=>(int)$alumno['intensivo_activo'],':i2'=>(int)$alumno['intensivo_activo']]);$mensajes=$st->fetchAll();
  out(['ok'=>true,'alumno'=>$alumno,'pagos'=>$pagos,'avisos'=>$avisos,'reposiciones'=>$repos,'intensivos'=>$intensivos,'mensajes'=>$mensajes]);
