 $in=json_decode(file_get_contents('php://input'),true);if(!is_array($in))out(['ok'=>false,'error'=>'JSON inválido'],400);$accion=strtoupper((string)($in['accion']??''));
 if($accion==='AVISO'){$desde=(string)($in['fecha_desde']??'');$hasta=(string)($in['fecha_hasta']??$desde);$motivo=trim((string)($in['motivo']??''));if(!$desde||!$hasta||$motivo==='')out(['ok'=>false,'error'=>'Completa las fechas y el motivo'],422);$d=DateTimeImmutable::createFromFormat('!Y-m-d',$desde);$h=DateTimeImmutable::createFromFormat('!Y-m-d',$hasta);if(!$d||!$h||$d->format('Y-m-d')!==$desde||$h->format('Y-m-d')!==$hasta)out(['ok'=>false,'error'=>'Las fechas no son válidas'],422);if($h<$d)out(['ok'=>false,'error'=>'La fecha final no puede ser anterior a la inicial'],422);if($h<new DateTimeImmutable('today'))out(['ok'=>false,'error'=>'El aviso debe corresponder a una fecha actual o futura'],422);if(mb_strlen($motivo)>500)out(['ok'=>false,'error'=>'El motivo no puede exceder 500 caracteres'],422);$pdo->beginTransaction();$st=$pdo->prepare("SELECT id FROM alumnos WHERE id=:a LIMIT 1 FOR UPDATE");$st->execute([':a'=>$aid]);if(!$st->fetchColumn()){$pdo->rollBack();out(['ok'=>false,'error'=>'Alumno no encontrado'],404);}$st=$pdo->prepare("SELECT 1 FROM avisos_ausencia WHERE alumno_id=:a AND fecha_desde=:d AND fecha_hasta=:h AND estado='ACTIVO' LIMIT 1");$st->execute([':a'=>$aid,':d'=>$desde,':h'=>$hasta]);if($st->fetchColumn()){$pdo->rollBack();out(['ok'=>false,'error'=>'Ya existe un aviso activo para ese mismo rango'],409);}$id=(string)$pdo->query("SELECT UUID()")->fetchColumn();$st=$pdo->prepare("INSERT INTO avisos_ausencia(id,alumno_id,fecha_desde,fecha_hasta,motivo,estado,created_by) VALUES(:id,:a,:d,:h,:m,'ACTIVO',:u)");$st->execute([':id'=>$id,':a'=>$aid,':d'=>$desde,':h'=>$hasta,':m'=>$motivo,':u'=>$me['id']]);$pdo->commit();out(['ok'=>true,'id'=>$id]);}
 if($accion==='CANCELAR_AVISO'){$id=(string)($in['id']??'');if($id==='')out(['ok'=>false,'error'=>'Aviso inválido'],422);$st=$pdo->prepare("UPDATE avisos_ausencia SET estado='CANCELADO' WHERE id=:id AND alumno_id=:a AND estado='ACTIVO'");$st->execute([':id'=>$id,':a'=>$aid]);if($st->rowCount()===0)out(['ok'=>false,'error'=>'Aviso activo no encontrado'],404);out(['ok'=>true]);}
 if($accion==='PERFIL'){$pais=strtoupper(trim((string)($in['whatsapp_pais']??'')));try{$wa=telefono_normalizar_entrada(trim((string)($in['whatsapp']??'')),$pais!==''?$pais:null);}catch(InvalidArgumentException $e){out(['ok'=>false,'error'=>$e->getMessage()],422);}$correo=trim((string)($in['correo']??''));if($correo!==''&&!filter_var($correo,FILTER_VALIDATE_EMAIL))out(['ok'=>false,'error'=>'El correo no es válido'],422);$pdo->beginTransaction();regla_bloquear_identidades_alumnos($pdo);$st=$pdo->prepare("SELECT nombre FROM alumnos WHERE whatsapp=:w AND id<>:a LIMIT 1");$st->execute([':w'=>$wa,':a'=>$aid]);if($dup=$st->fetch()){$pdo->rollBack();out(['ok'=>false,'error'=>'Ese WhatsApp ya pertenece a '.$dup['nombre']],409);}$st=$pdo->prepare("UPDATE alumnos SET whatsapp=:w,correo=:c,updated_at=NOW() WHERE id=:a");$st->execute([':w'=>$wa,':c'=>$correo?:null,':a'=>$aid]);$pdo->commit();out(['ok'=>true]);}
 out(['ok'=>false,'error'=>'Acción inválida'],422);
}catch(Throwable $e){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();error_log('[portal-alumno] '.$e->getMessage());out(['ok'=>false,'error'=>'No se pudo procesar la solicitud'],500);}
